// ==================== 删除确认弹窗 ====================
function confirmDeleteSession() {
  const sessionId = deleteTargetSessionId.value
  if (!sessionId) return
  
  const idx = sessions.value.findIndex((s) => s.id === sessionId)
  if (idx >= 0) {
    sessions.value.splice(idx, 1)
    if (activeSessionId.value === sessionId) {
      if (sessions.value.length > 0) {
        activeSessionId.value = sessions.value[0].id
      } else {
        openNewSession()
      }
    }
  }
  activeMenuId.value = null
  showDeleteModal.value = false
  deleteTargetSessionId.value = null
}

function cancelDeleteSession() {
  showDeleteModal.value = false
  deleteTargetSessionId.value = null
}

// ==================== 场景识别函数 ====================
function detectScene(text) {
  const lowerText = text.toLowerCase()
  
  // 优先检查咨询模式问题（以疑问词开头）- 咨询模式优先级最高
  const consultationPatterns = ['什么是', '有哪些', '怎么判断', '为什么', '会不会', '能不能', '是否', '如何', '啥是', '什么叫', '何为']
  for (const pattern of consultationPatterns) {
    if (lowerText.includes(pattern)) {
      console.log(`🎯 咨询模式识别: knowledge (匹配: ${pattern})`)
      return 'knowledge'
    }
  }
  
  // 检查科普场景
  for (const kw of sceneKeywords.knowledge) {
    if (lowerText.includes(kw.toLowerCase())) {
      return 'knowledge'
    }
  }
  
  // 检查风险场景（诈骗相关）- 反诈预警模式
  for (const kw of sceneKeywords.risk) {
    if (lowerText.includes(kw.toLowerCase())) {
      console.log(`🎯 反诈预警模式识别: risk_detect (匹配: ${kw})`)
      return 'risk_detect'
    }
  }
  
  // 检查闲聊场景
  for (const kw of sceneKeywords.chat) {
    if (lowerText.includes(kw.toLowerCase())) {
      return 'chat'
    }
  }
  
  // 默认为闲聊场景
  return 'chat'
}

// 自动识别用户角色（优化版：多维度识别）
