// ==================== 长期记忆：角色记忆 ====================
function saveRoleToMemory(role) {
  try {
    localStorage.setItem(ROLE_STORAGE_KEY, JSON.stringify({
      role: role,
      timestamp: Date.now(),
      detectedAt: new Date().toLocaleString('zh-CN')
    }))
    console.log(`💾 角色已保存到长期记忆: ${role}`)
  } catch (e) {
    console.warn('保存角色记忆失败:', e)
  }
}

function loadRoleFromMemory() {
  try {
    const saved = localStorage.getItem(ROLE_STORAGE_KEY)
    if (saved) {
      const data = JSON.parse(saved)
      console.log(`📂 从长期记忆加载角色: ${data.role} (识别于: ${data.detectedAt})`)
      return data.role
    }
  } catch (e) {
    console.warn('加载角色记忆失败:', e)
  }
  return null
}

// ==================== 风险记忆：历史风险对话 ====================
function saveRiskToMemory(riskData) {
  try {
    const existing = JSON.parse(localStorage.getItem(RISK_MEMORY_KEY) || '[]')
    existing.push({
      ...riskData,
      timestamp: Date.now(),
      detectedAt: new Date().toLocaleString('zh-CN')
    })
    // 只保留最近20条风险记录
    const trimmed = existing.slice(-20)
    localStorage.setItem(RISK_MEMORY_KEY, JSON.stringify(trimmed))
    console.log(`💾 风险已保存到记忆库，当前共 ${trimmed.length} 条记录`)
  } catch (e) {
    console.warn('保存风险记忆失败:', e)
  }
}

function loadRiskMemory() {
  try {
    const saved = localStorage.getItem(RISK_MEMORY_KEY)
    if (saved) {
      return JSON.parse(saved)
    }
  } catch (e) {
    console.warn('加载风险记忆失败:', e)
  }
  return []
}

// ==================== 短期记忆：最近对话 ====================
function saveShortMemory(sessionId, message) {
  try {
    const key = `${SHORT_MEMORY_KEY}-${sessionId}`
    const existing = JSON.parse(localStorage.getItem(key) || '[]')
    existing.push({
      content: message.content,
      role: message.role,
      timestamp: Date.now()
    })
    // 只保留最近20轮对话
    const trimmed = existing.slice(-40) // 20轮 = 40条消息
    localStorage.setItem(key, JSON.stringify(trimmed))
  } catch (e) {
    console.warn('保存短期记忆失败:', e)
  }
}

function loadShortMemory(sessionId) {
  try {
    const key = `${SHORT_MEMORY_KEY}-${sessionId}`
    const saved = localStorage.getItem(key)
    if (saved) {
      return JSON.parse(saved)
    }
  } catch (e) {
    console.warn('加载短期记忆失败:', e)
  }
  return []
}

