  return [...sessions.value].sort((a, b) => {
    if (a.pinned && !b.pinned) return -1
    if (!a.pinned && b.pinned) return 1
    return 0
  })
})

function createId(prefix = 'id') {
  if (typeof crypto !== 'undefined' && crypto.randomUUID) {
    return `${prefix}-${crypto.randomUUID()}`
  }
  return `${prefix}-${Date.now()}-${Math.random().toString(36).slice(2, 10)}`
}

function createSession() {
  return {
    id: createId('session'),
    chatId: createId('chat'),
    title: '新对话',
    messages: [],
    pinned: false,
    welcomeShown: false,
  }
}

function formatDuration(totalSeconds) {
  const seconds = Math.max(0, Math.floor(totalSeconds))
  const mm = String(Math.floor(seconds / 60)).padStart(2, '0')
  const ss = String(seconds % 60).padStart(2, '0')
  return `${mm}:${ss}`
}

// 防抖函数
function debounce(fn, delay) {
  let timer = null
  return function(...args) {
    if (timer) clearTimeout(timer)
    timer = setTimeout(() => {
      fn.apply(this, args)
    }, delay)
  }
}

// 清理旧会话数据
function clearOldSessions() {
  try {
    const recentSessions = sessions.value.slice(-5)
    sessions.value = recentSessions
    const payload = {
      activeSessionId: activeSessionId.value,
      sessions: recentSessions.map(session => ({
        ...session,
        messages: session.messages.slice(-50)
      })),
      savedAt: Date.now()
    }
    localStorage.setItem(STORAGE_KEY, JSON.stringify(payload))
    console.log('已清理旧会话数据')
  } catch (error) {
    localStorage.removeItem(STORAGE_KEY)
    console.warn('存储空间不足，已清空会话数据')
  }
}

function persistSessions() {
  try {
    // 清理媒体文件的 base64 数据，只保留元信息
    const cleanedSessions = sessions.value.map(session => ({
      ...session,
      messages: session.messages.map(msg => {
        if (msg.media && msg.media.length > 0) {
          return {
            ...msg,
            media: msg.media.map(m => ({
              type: m.type,
              name: m.name,
            }))
          }
        }
        return msg
      })
    }))

    // 限制保存的会话数量（最多 20 个）和每个会话的消息数量（最多 50 条）
    const limitedSessions = cleanedSessions.slice(-20).map(session => ({
      ...session,
      messages: session.messages.slice(-50)
    }))

    const payload = {
      activeSessionId: activeSessionId.value,
      sessions: limitedSessions,
      savedAt: Date.now()
    }

    localStorage.setItem(STORAGE_KEY, JSON.stringify(payload))
  } catch (error) {
    console.error('会话持久化失败:', error)
    if (error.name === 'QuotaExceededError') {
      clearOldSessions()
    }
  }
}

// 使用防抖的持久化函数
const debouncedPersistSessions = debounce(persistSessions, 1000)

function restoreSessions() {
  const raw = localStorage.getItem(STORAGE_KEY)
  if (!raw) return false
  try {
    const parsed = JSON.parse(raw)
    if (!Array.isArray(parsed?.sessions) || !parsed.sessions.length) return false
    sessions.value = parsed.sessions
    const hasActive = parsed.activeSessionId && sessions.value.some((item) => item.id === parsed.activeSessionId)
    activeSessionId.value = hasActive ? parsed.activeSessionId : sessions.value[0].id
    return true
  } catch (error) {
    localStorage.removeItem(STORAGE_KEY)
    return false
  }
}

