function truncateTitle(text) {
  const normalized = text.replace(/\s+/g, ' ').trim()
  if (!normalized) return '新对话'
  return normalized.length > 18 ? `${normalized.slice(0, 18)}…` : normalized
}

function updateSessionTitle(session, text) {
  if (!session || !text || session.title !== '新对话') return
  session.title = truncateTitle(text)
}

function addMessage(session, payload) {
  const message = {
    id: createId('msg'),
    createdAt: Date.now(),
    ...payload,
  }
  session.messages.push(message)
  
  // 保存assistant消息到短期记忆
  if (payload.role === 'assistant') {
    saveShortMemory(session.id, { role: payload.role, content: payload.content })
  }
}

function fileToDataUrl(file) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader()
    reader.onload = () => resolve(String(reader.result || ''))
    reader.onerror = () => reject(reader.error)
    reader.readAsDataURL(file)
  })
}

function scrollToBottom() {
  nextTick(() => {
    const el = listRef.value
    if (!el) return
    el.scrollTop = el.scrollHeight
  })
}

