// 性能优化：复用 canvas 对象，避免重复创建
const imageCompressCanvas = document.createElement('canvas')
const imageCompressCtx = imageCompressCanvas.getContext('2d')

// 图片压缩函数（性能优化：更激进的压缩参数 + 内存释放）
function compressImage(file, maxWidth = 800, quality = 0.7) {
  return new Promise((resolve, reject) => {
    const img = new Image()
    
    img.onload = () => {
      let width = img.width
      let height = img.height
      
      if (width > maxWidth) {
        height = (height * maxWidth) / width
        width = maxWidth
      }
      
      imageCompressCanvas.width = width
      imageCompressCanvas.height = height
      
      imageCompressCtx.drawImage(img, 0, 0, width, height)
      
      const compressedDataUrl = imageCompressCanvas.toDataURL('image/jpeg', quality)
      
      // 性能优化：释放内存
      URL.revokeObjectURL(img.src)
      
      resolve(compressedDataUrl)
    }
    
    img.onerror = (err) => {
      URL.revokeObjectURL(img.src)
      reject(err)
    }
    img.src = URL.createObjectURL(file)
  })
}

