// ==================== 文本净化函数（OCR文本专用） ====================
function purifyText(text) {
  if (!text) return ''
  
  // 第一步：移除常见的OCR乱码前缀模式
  let purified = text
    // 移除 "plaintext"、"ciphertext" 等标签
    .replace(/^plaintext\s*/i, '')
    .replace(/^ciphertext\s*/i, '')
    // 移除开头的特殊符号组合（如 ~ 团心 & 0 等乱码）
    .replace(/^[~`!@#$%^&*()_+=\[\]{}|\\;:'",.<>?\/\s\uff00-\uffef]+/, '')
    // 移除常见的噪点字符串模式
    .replace(/^[a-zA-Z0-9\s&~@#%^*_+=|\\<>/-]{1,30}[\u4e00-\u9fa5]/, (match) => {
      // 只保留中文字符部分
      const chinese = match.match(/[\u4e00-\u9fa5]+/g)
      return chinese ? chinese.join('') : ''
    })
  
  // 第二步：移除所有类型的空格（全角、半角、制表符）
  purified = purified
    .replace(/[\u3000\u00A0\s\t]+/g, '') // 全角空格、不间断空格、普通空格、制表符
  
  // 第三步：移除换行符
  purified = purified
    .replace(/[\r\n\f\v]+/g, '')
  
  // 第四步：移除特殊符号，只保留中文、数字、基本标点
  // 保留：中文、数字、中文标点（，。！？、；：""''《》【】（））、英文标点（,.!?;:'"()）
  purified = purified
    .replace(/[^\u4e00-\u9fa5\u0030-\u0039\uFF10-\uFF19\u3000-\u303F\uFF00-\uFFEF.,!?;:'"()\[\]{}《》【】（），。！？、；：""'']/g, '')
  
  // 第五步：最终清理，移除首尾残留的空白
  purified = purified.trim()
  
  console.log('🧹 文本净化结果:')
  console.log('   原始:', JSON.stringify(text.substring(0, 100)) + (text.length > 100 ? '...' : ''))
  console.log('   净化后:', JSON.stringify(purified.substring(0, 100)) + (purified.length > 100 ? '...' : ''))
  
  return purified
}

// ==================== 反诈识别核心函数 ====================
function detectFraud(text) {
  console.log('========== 反诈识别开始 ==========')
  console.log('📝 原始文本:', JSON.stringify(text))
  
  if (!text || !text.trim()) {
    console.log('⚠️ 文本为空，返回无风险')
    return { riskLevel: 'none', fraudType: '无内容', confidence: 1, matchedCases: [], keywords: [], userRole: userRole.value, scene: 'chat' }
  }
  
  // 文本净化：彻底清理OCR噪点，只保留有效中文、数字、标点
  const purifiedText = purifyText(text)
  
  if (!purifiedText) {
    console.log('⚠️ 净化后文本为空，返回无风险')
    return { riskLevel: 'none', fraudType: '无有效内容', confidence: 1, matchedCases: [], keywords: [], userRole: userRole.value, scene: 'chat' }
  }
  
  // ========== 场景识别 ==========
  const detectedScene = detectScene(purifiedText)
  currentScene.value = detectedScene
  console.log(`🎬 当前场景: ${detectedScene}`)
  
  // ========== 自动角色识别 ==========
  const detectedRole = detectUserRole(purifiedText)
  if (detectedRole && detectedRole !== userRole.value) {
    const prevRole = userRole.value
    userRole.value = detectedRole
    saveRoleToMemory(detectedRole)
    console.log(`🎭 角色已自动切换为: ${detectedRole}`)
    
    // 同步更新用户信息中的角色
    const roleInfo = profileRoleOptions.find(opt => opt.value === detectedRole)
    if (roleInfo) {
      updateUserRole(detectedRole)
    }
  }
  
  const result = {
    riskLevel: 'none',
    fraudType: '未识别出诈骗类型',
    confidence: 0,
    matchedCases: [],
    keywords: [],
    guardianNotified: false,
    userRole: userRole.value,
    baseRiskLevel: 'none',
    roleDetected: detectedRole,
    scene: detectedScene,
  }
  
  // ========== 闲聊/科普场景：直接返回无风险，不触发任何报告 ==========
  if (detectedScene === 'chat') {
    console.log('💬 闲聊场景，不触发风险检测')
    result.fraudType = '日常闲聊'
    result.confidence = 0.95
    return result
  }
  
  if (detectedScene === 'knowledge') {
    console.log('📚 科普场景，不触发风险检测')
    result.fraudType = '反诈知识咨询'
    result.confidence = 0.95
    return result
  }
  
  // ========== 风险检测场景：进行完整的风险分析 ==========
  
  // 1. 先进行知识库匹配（知识库优先）
  const matchedCases = []
  
  // 通用知识库匹配检索
  fraudKnowledgeBase.forEach(item => {
    const matchedKws = item.keywords.filter(kw => purifiedText.includes(kw))
    if (matchedKws.length > 0) {
      const similarity = Math.min(0.95, matchedKws.length / item.keywords.length + matchedKws.length * 0.1)
      matchedCases.push({
        id: item.id,
        type: item.type,
        riskLevel: item.riskLevel,
        similarity: similarity.toFixed(2),
        matchedKeywords: matchedKws,
        defense: item.defense,
        source: '通用知识库',
      })
    }
  })
  
  // 财会人员专属知识库匹配
  if (userRole.value === 'accountant') {
    console.log('💼 启用财会人员专属知识库...')
    accountantKnowledgeBase.forEach(item => {
      const matchedKws = item.keywords.filter(kw => purifiedText.includes(kw))
      if (matchedKws.length > 0) {
        const similarity = Math.min(0.98, matchedKws.length / item.keywords.length + matchedKws.length * 0.15)
        matchedCases.push({
          id: item.id,
          type: item.type,
          riskLevel: item.riskLevel,
          similarity: similarity.toFixed(2),
          matchedKeywords: matchedKws,
          defense: item.defense,
          source: '财会专属知识库',
        })
      }
    })
  }
  
  // 自由职业者专属知识库匹配
  if (userRole.value === 'worker') {
    console.log('👔 启用自由职业者专属知识库...')
    workerKnowledgeBase.forEach(item => {
      const matchedKws = item.keywords.filter(kw => purifiedText.includes(kw))
      if (matchedKws.length > 0) {
        const similarity = Math.min(0.98, matchedKws.length / item.keywords.length + matchedKws.length * 0.15)
        matchedCases.push({
          id: item.id,
          type: item.type,
          riskLevel: item.riskLevel,
          similarity: similarity.toFixed(2),
          matchedKeywords: matchedKws,
          defense: item.defense,
          source: '自由职业者专属知识库',
        })
      }
    })
  }
  
  // 老年人专属知识库匹配
  if (userRole.value === 'elderly') {
    console.log('👴 启用老年人专属知识库...')
    elderlyKnowledgeBase.forEach(item => {
      const matchedKws = item.keywords.filter(kw => purifiedText.includes(kw))
      if (matchedKws.length > 0) {
        const similarity = Math.min(0.98, matchedKws.length / item.keywords.length + matchedKws.length * 0.15)
        matchedCases.push({
          id: item.id,
          type: item.type,
          riskLevel: item.riskLevel,
          similarity: similarity.toFixed(2),
          matchedKeywords: matchedKws,
          defense: item.defense,
          source: '老年专属知识库',
        })
      }
    })
  }
  
  // 青少年专属知识库匹配
  if (userRole.value === 'youth') {
    console.log('👦 启用青少年专属知识库...')
    youthKnowledgeBase.forEach(item => {
      const matchedKws = item.keywords.filter(kw => purifiedText.includes(kw))
      if (matchedKws.length > 0) {
        const similarity = Math.min(0.98, matchedKws.length / item.keywords.length + matchedKws.length * 0.15)
        matchedCases.push({
          id: item.id,
          type: item.type,
          riskLevel: item.riskLevel,
          similarity: similarity.toFixed(2),
          matchedKeywords: matchedKws,
          defense: item.defense,
          source: '青少年专属知识库',
        })
      }
    })
  }
  
  // 少儿专属知识库匹配
  if (userRole.value === 'child') {
    console.log('👶 启用少儿专属知识库...')
    childKnowledgeBase.forEach(item => {
      const matchedKws = item.keywords.filter(kw => purifiedText.includes(kw))
      if (matchedKws.length > 0) {
        const similarity = Math.min(0.98, matchedKws.length / item.keywords.length + matchedKws.length * 0.15)
        matchedCases.push({
          id: item.id,
          type: item.type,
          riskLevel: item.riskLevel,
          similarity: similarity.toFixed(2),
          matchedKeywords: matchedKws,
          defense: item.defense,
          source: '少儿专属知识库',
        })
      }
    })
  }
  
  // 按相似度排序，但优先选择匹配关键词数量更多的案例（更精确匹配）
  matchedCases.sort((a, b) => {
    // 首先按匹配关键词数量排序（越多越精确）
    const aKwCount = a.matchedKeywords.length
    const bKwCount = b.matchedKeywords.length
    if (aKwCount !== bKwCount) {
      return bKwCount - aKwCount
    }
    // 其次按相似度排序
    return b.similarity - a.similarity
  })
  result.matchedCases = matchedCases.slice(0, 3)
  
  // 2. 知识库匹配成功时，以知识库风险等级为准（优先级最高）
  if (matchedCases.length > 0) {
    const topCase = matchedCases[0]
    result.fraudType = topCase.type
    result.riskLevel = topCase.riskLevel
    result.confidence = parseFloat(topCase.similarity)
    result.keywords = [...topCase.matchedKeywords]
    console.log(`📚 知识库匹配成功: ${topCase.type}, 风险等级: ${topCase.riskLevel}, 来源: ${topCase.source}, 匹配关键词数: ${topCase.matchedKeywords.length}`)
  } else {
    // 3. 知识库未匹配时，使用关键词匹配作为补充
    const foundHighKeywords = highRiskKeywords.filter(kw => purifiedText.includes(kw))
    console.log('🔍 高风险关键词匹配:', foundHighKeywords)
    if (foundHighKeywords.length > 0) {
      result.riskLevel = 'high'
      result.keywords = foundHighKeywords
      result.confidence = 0.85 + foundHighKeywords.length * 0.03
    }
    
    const foundMediumKeywords = mediumRiskKeywords.filter(kw => purifiedText.includes(kw))
    console.log('🔍 中风险关键词匹配:', foundMediumKeywords)
    if (foundMediumKeywords.length > 0 && result.riskLevel === 'none') {
      result.riskLevel = 'medium'
      result.keywords = foundMediumKeywords
      result.confidence = 0.6 + foundMediumKeywords.length * 0.05
    }
    
    const lowRiskKeywords = ['可疑', '奇怪', '不太对', '感觉有问题', '不太相信', '有点担心']
    const foundLowKeywords = lowRiskKeywords.filter(kw => purifiedText.includes(kw))
    if (foundLowKeywords.length > 0 && result.riskLevel === 'none') {
      result.riskLevel = 'low'
      result.keywords = foundLowKeywords
      result.confidence = 0.4 + foundLowKeywords.length * 0.05
    }
  }
  
  console.log('📊 当前风险等级:', result.riskLevel, '| 匹配关键词:', result.keywords)
  
  // 4. 正常文本检测
  const normalIndicators = ['天气', '散步', '公园', '超市', '水果', '蔬菜', '做饭', '吃饭', '你好', '谢谢']
  const normalCount = normalIndicators.filter(w => purifiedText.includes(w)).length
  if (normalCount >= 2 && result.riskLevel === 'none' && matchedCases.length === 0) {
    result.fraudType = '正常对话'
    result.confidence = 0.95
  }
  
  // 5. 记录原始风险等级（角色调整前）
  result.baseRiskLevel = result.riskLevel
  console.log('📌 基础风险等级（角色调整前）:', result.baseRiskLevel)
  
  // 6. 风险等级完全依据知识库判定，不再进行角色自动升级
  // 删除旧版「职业+关键词自动升一级」的错误规则
  // 风险等级以知识库定义为准，保持一致性
  
  // 7. 高风险时标记监护人通知，并保存风险记忆
  if (result.riskLevel === 'high') {
    result.guardianNotified = true
    // 保存风险记忆
    saveRiskToMemory({
      text: text.substring(0, 200),
      riskLevel: result.riskLevel,
      fraudType: result.fraudType,
      keywords: result.keywords,
      userRole: result.userRole
    })
  }
  
  result.confidence = Math.min(0.99, result.confidence).toFixed(2)
  
  console.log('========== 反诈识别结束 ==========')
  console.log('🎯 最终结果:', {
    场景: result.scene,
    风险等级: result.riskLevel,
    诈骗类型: result.fraudType,
    置信度: result.confidence,
    关键词: result.keywords,
    用户角色: result.userRole
  })
  
  return result
}

// ==================== 图片专属风险检测函数（遍历所有角色知识库） ====================
function detectImageRisk(text) {
  const purifiedText = text.toLowerCase()
  const result = {
    riskLevel: 'none',
    fraudType: '未知',
    confidence: 0,
    keywords: [],
    userRole: userRole.value
  }
  
  // 合并所有角色的知识库
  const allKnowledgeBases = [
    { name: '财会人员', base: accountantKnowledgeBase, role: 'accountant' },
    { name: '自由职业者', base: workerKnowledgeBase, role: 'worker' },
    { name: '老年人', base: elderlyKnowledgeBase, role: 'elderly' },
    { name: '青少年', base: youthKnowledgeBase, role: 'youth' },
    { name: '少儿', base: childKnowledgeBase, role: 'child' }
  ]
  
  const matchedCases = []
  
  // 遍历所有知识库进行匹配
  allKnowledgeBases.forEach(({ name, base, role }) => {
    base.forEach(item => {
      const matchedKws = item.keywords.filter(kw => purifiedText.includes(kw.toLowerCase()))
      if (matchedKws.length > 0) {
        const similarity = Math.min(0.98, matchedKws.length / item.keywords.length + matchedKws.length * 0.15)
        matchedCases.push({
          id: item.id,
          type: item.type,
          riskLevel: item.riskLevel,
          similarity: similarity.toFixed(2),
          matchedKeywords: matchedKws,
          defense: item.defense,
          source: `${name}专属知识库`,
          role: role
        })
      }
    })
  })
  
  // 按风险等级和匹配度排序
  const riskOrder = { 'high': 3, 'medium': 2, 'low': 1, 'none': 0 }
  matchedCases.sort((a, b) => {
    // 首先按风险等级排序
    if (riskOrder[a.riskLevel] !== riskOrder[b.riskLevel]) {
      return riskOrder[b.riskLevel] - riskOrder[a.riskLevel]
    }
    // 其次按匹配关键词数量排序
    return b.matchedKeywords.length - a.matchedKeywords.length
  })
  
  if (matchedCases.length > 0) {
    const topCase = matchedCases[0]
    result.fraudType = topCase.type
    result.riskLevel = topCase.riskLevel
    result.confidence = parseFloat(topCase.similarity)
    result.keywords = [...topCase.matchedKeywords]
    result.userRole = topCase.role
    console.log(`📷 图片风险检测: ${topCase.type}, 风险等级: ${topCase.riskLevel}, 来源: ${topCase.source}, 匹配关键词: ${topCase.matchedKeywords.join(', ')}`)
  }
  
  return result
}

// ==================== AI劝导话术 ====================
const API_BASE = import.meta.env.VITE_API_BASE?.replace(/\/$/, '') || 'http://localhost:8123/api'

async function fetchPersuasion(fraudType, riskLevel, userRole) {
  try {
    const res = await fetch(`${API_BASE}/v1/persuasion`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ fraud_type: fraudType, risk_level: riskLevel, user_role: userRole }),
    })
    const data = await res.json()
    if (data.success && data.message) {
      return data.message
    }
  } catch (e) {
    console.warn('获取劝导话术失败:', e)
  }
  return null
}

// ==================== 分级响应处理函数 ====================
function handleRiskResult(result, text, session) {
  if (!session) return
  
  riskResult.value = { ...result, text }

  // ========== 无风险/闲聊/科普场景：AI已正常回复，无需额外处理 ==========
  if (result.riskLevel === 'none' || result.scene === 'chat' || result.scene === 'knowledge') {
    console.log('✅ 无风险场景，AI已正常回复')
    return
  }

  // ========== 低风险：在AI回复后追加温馨提示 ==========
  if (result.riskLevel === 'low') {
    console.log('🟡 低风险场景，追加温馨提示')
    const tip = getRoleBasedTip(result.userRole, 'low')
    const lastMsg = session.messages[session.messages.length - 1]
    if (lastMsg && lastMsg.role === 'assistant') {
      lastMsg.content += `\n\n💡 温馨提示：${tip}`
    }
    return
  }

  // ========== 中风险：弹窗预警 ==========
  if (result.riskLevel === 'medium') {
    console.log('🟠 中风险场景，触发中风险预警弹窗')
    // 保存风险记忆
    saveRiskToMemory({
      text: text.substring(0, 200),
      riskLevel: result.riskLevel,
      fraudType: result.fraudType,
      keywords: result.keywords,
      userRole: result.userRole
    })
    // 显示中风险弹窗
    showMediumRiskModal.value = true
    return
  }

  // ========== 高风险：弹窗预警 + 安全监测报告 + 监护人联动 + AI劝导 ==========
  if (result.riskLevel === 'high') {
    console.log('🚨 高风险场景，触发完整预警流程')
    // 保存风险记忆
    saveRiskToMemory({
      text: text.substring(0, 200),
      riskLevel: result.riskLevel,
      fraudType: result.fraudType,
      keywords: result.keywords,
      userRole: result.userRole
    })
    // 在聊天界面添加系统消息
    addMessage(session, {
      role: 'system',
      type: 'text',
      content: `🚨 已向监护人 ${guardianPhone} 发送高危预警`,
    })
    // 获取AI劝导话术
    reportGenerated.value = false
    showPersuasion.value = false
    persuasionMessage.value = ''
    fetchPersuasion(result.fraudType, result.riskLevel, userInfo.value.role || 'default').then(msg => {
      if (msg) {
        persuasionMessage.value = msg
        showPersuasion.value = true
      }
    })
    // 显示风险弹窗
    showRiskModal.value = true
  }
}

