    <li><strong>📋 保存聊天记录</strong>、转账截图等所有证据</li>
  </ul>

  ${result.matchedCases?.[0]?.defense ? `
  <h2>🔒 加强防范</h2>
  <p style="font-size:13px;padding:8px 12px;background:#f5f7fa;border-radius:6px;">${result.matchedCases[0].defense}</p>
  ` : ''}

  ${persuasionMessage.value ? `
  <h2>💬 反诈卫士提醒您</h2>
  <div class="persuasion-box">${persuasionMessage.value}</div>
  ` : ''}

  <h2>📞 紧急联系方式</h2>
  <div class="contact-box">
    <strong>报警电话：</strong>110<br>
    <strong>反诈专线：</strong>96110<br>
    <strong>银行客服：</strong>请拨打银行卡背面客服电话
  </div>

  <div class="footer">
    <p>本报告由 AI 反诈智能体自动生成，仅供参考，不构成法律意见。</p>
    <p>如有紧急情况，请立即拨打 110 报警。</p>
  </div>
</body>
</html>`

  // 在新窗口中打开并打印
  const printWindow = window.open('', '_blank')
  if (printWindow) {
    printWindow.document.write(htmlContent)
    printWindow.document.close()
    printWindow.focus()
    setTimeout(() => {
      printWindow.print()
    }, 500)
  }
}

// 生成视频第一帧作为海报图
function generateVideoPoster(videoUrl) {
  return new Promise((resolve) => {
    const video = document.createElement('video')
    video.crossOrigin = 'anonymous'
    video.preload = 'auto'
    video.muted = true
    video.playsInline = true
    video.src = videoUrl

    let resolved = false
    const safeResolve = (val) => {
      if (!resolved) {
        resolved = true
        resolve(val)
      }
    }

    // 加载元数据后尝试获取第一帧
    video.addEventListener('loadedmetadata', () => {
      try {
        // 设置到第一帧附近
        video.currentTime = Math.min(0.5, (video.duration || 1) * 0.05)
      } catch (e) {
        // 忽略
      }
    })

    // 视频数据可绘制时
    video.addEventListener('loadeddata', () => {
      try {
        drawFrame()
      } catch (e) {
        safeResolve('')
      }
    })

    // 视频可播放时再尝试
    video.addEventListener('canplay', () => {
      try {
        drawFrame()
      } catch (e) {
        safeResolve('')
      }
    })

    function drawFrame() {
      const w = video.videoWidth || 320
      const h = video.videoHeight || 240
      const canvas = document.createElement('canvas')
      canvas.width = w
      canvas.height = h
      const ctx = canvas.getContext('2d')
      ctx.drawImage(video, 0, 0, w, h)
      const posterUrl = canvas.toDataURL('image/jpeg', 0.6)
      safeResolve(posterUrl)
    }

    video.addEventListener('error', () => safeResolve(''))

    // 超时处理（5秒）
    setTimeout(() => {
      if (video.readyState >= 2) {
        try { drawFrame() } catch (e) { safeResolve('') }
      } else {
        safeResolve('')
      }
    }, 5000)
  })
}

// AI生成安全报告
function generateSecurityReport() {
  const session = activeSession.value
  if (!session || !riskResult.value) return

  const result = riskResult.value
  const roleLabel = userInfo.value.roleLabel || '中青年'

  reportGenerated.value = true

  // 构建安全报告内容（仅高风险时生成完整报告）
  let reportContent = ''

  if (result.riskLevel === 'high') {
    reportContent += `🚨 **高危预警！请立即查看！**\n\n`
    reportContent += `检测到您正在遭遇「${result.fraudType}」，请立即按照以下步骤操作：\n\n`
    
    reportContent += `**第一步：立即止损**\n`
    reportContent += `1. 立刻停止所有转账、汇款操作\n`
    reportContent += `2. 如果已经转账，马上拨打银行客服申请紧急止付\n`
    reportContent += `3. 不要相信对方说的任何「解冻」「安全账户」「保证金」\n\n`

    reportContent += `**第二步：立即报警**\n`
    reportContent += `1. 拨打 110 报警电话，说明遭遇了「${result.fraudType}」\n`
    reportContent += `2. 前往最近的派出所，带上手机和聊天记录\n`
    reportContent += `3. 报警越及时，追回损失的可能性越大\n\n`

    reportContent += `**第三步：保留证据**\n`
    reportContent += `1. 截图保存所有聊天记录（不要删除！）\n`
    reportContent += `2. 保存转账记录、银行流水\n`
    reportContent += `3. 记录对方账号、电话、微信号等所有信息\n\n`

    // 防御指南
    if (result.matchedCases?.[0]?.defense) {
      reportContent += `**第四步：加强防范**\n`
      reportContent += `${result.matchedCases[0].defense}\n\n`
    }

    // 添加AI劝导话术（实用话术，让用户看清骗局）
    if (persuasionMessage.value) {
      reportContent += `**💬 反诈卫士提醒您**\n`
      reportContent += `${persuasionMessage.value}\n\n`
    }

    reportContent += `**📞 紧急联系方式**\n`
    reportContent += `- 报警电话：110\n`
    reportContent += `- 反诈专线：96110\n`
    reportContent += `- 银行客服：请拨打银行卡背面客服电话\n\n`

    reportContent += `💡 您主动来核实是非常正确的决定！${roleLabel}群体是诈骗分子的重点目标，保持警惕就是最好的防护。`
  }

  // 添加AI消息
  if (reportContent) {
    addMessage(session, {
      role: 'assistant',
      type: 'text',
      content: reportContent,
    })
  }
}

// 发送消息入口
async function send() {
  const session = activeSession.value
  if (!session || !canSend.value) return

  const text = input.value.trim()
  const media = [...pendingMedia.value]
  
  // 清空输入和预览
  input.value = ''
  clearPendingMedia()
  
  // 如果没有文字也没有媒体，直接返回
  if (!text && media.length === 0) return

  loading.value = true

  // 构建用户消息
  const userMessage = {
    role: 'user',
    type: 'multimedia',
    content: text,
    media: media.map(m => ({
      type: m.type,
      url: m.url,
      name: m.name,
    })),
  }
  addMessage(session, userMessage)
  
  // 保存到短期记忆
  if (text) {
    saveShortMemory(session.id, { role: 'user', content: text })
  }
  
  updateSessionTitle(session, text || media[0]?.name || '多媒体消息')

  // 检查是否有视频文件（视频分析已包含AI回答，需要特殊处理）
  const videoFiles = media.filter(m => m.type === 'video')
  const otherMedia = media.filter(m => m.type !== 'video')

  // 处理视频文件（视频分析已包含AI回答）
  if (videoFiles.length > 0) {
    for (const videoFile of videoFiles) {
      try {
        console.log('🎬 开始视频分析...', videoFile.name)
        const videoResult = await analyzeVideoFile(videoFile.file)
        
        if (videoResult && videoResult.aiResponse) {
          // 创建AI回复消息
          const aiMessage = { 
            role: 'assistant', 
            type: 'text', 
            content: videoResult.aiResponse 
          }
          session.messages.push({
            id: createId('msg'),
            createdAt: Date.now(),
            ...aiMessage,
          })
          
          // 保存到短期记忆
          const fullVideoText = text ? `${text}\n[视频内容] ${videoResult.description}` : `[视频内容] ${videoResult.description}`
          saveShortMemory(session.id, { role: 'user', content: fullVideoText })
          saveShortMemory(session.id, { role: 'assistant', content: videoResult.aiResponse })
          
          // 使用detectImageRisk检测视频内容风险（遍历所有角色知识库）
          const videoRiskResult = detectImageRisk(fullVideoText)
          
          // 如果视频内容没检测到风险，再检测AI回答内容
          let finalVideoRiskResult = videoRiskResult
          if (videoRiskResult.riskLevel === 'none' || videoRiskResult.riskLevel === 'low') {
            const aiVideoRiskResult = detectImageRisk(videoResult.aiResponse)
            if (aiVideoRiskResult.riskLevel === 'high' || aiVideoRiskResult.riskLevel === 'medium') {
              console.log('🎬 AI回答中检测到风险:', aiVideoRiskResult.riskLevel, aiVideoRiskResult.fraudType)
              finalVideoRiskResult = aiVideoRiskResult
            }
          }
          
          // 统一使用handleRiskResult处理风险结果（弹窗逻辑与反诈骗模式一致）
          handleRiskResult(finalVideoRiskResult, fullVideoText, session)
        }
      } catch (error) {
        console.error('🎬 视频分析失败:', error)
      }
    }
    
    // 如果还有其他媒体文件或文字，继续处理
    if (otherMedia.length === 0 && !text) {
      loading.value = false
      return
    }
  }

  // 处理其他媒体识别（图片、音频）
  const mediaPromises = otherMedia.map(async (m) => {
    if (m.type === 'image') {
      const result = await visionModelImage(m.url)
      return result ? `[图片内容] ${result}` : null
    } else if (m.type === 'audio') {
      let result = await asrAudioReal(m.file, m.url)
      if (!result) {
        result = await asrAudio(m.file, m.url)
      }
      return result ? `[语音内容] ${result}` : null
    }
    return null
  })
  
  const recognizedTexts = (await Promise.all(mediaPromises)).filter(Boolean)

  // 合并文字和识别结果
  const fullText = [text, ...recognizedTexts].filter(Boolean).join('\n')
  
  // 如果没有文字内容，直接返回
  if (!fullText) {
    loading.value = false
    return
  }
  
  // 检测是否包含图片内容
  const hasImageContent = recognizedTexts.some(t => t && t.includes('[图片内容]'))
  
  // 如果是图片，使用图片专属风险检测（遍历所有角色知识库）
  let riskResult
  if (hasImageContent) {
    console.log('📷 检测到图片内容，启用图片专属风险检测...')
    riskResult = detectImageRisk(fullText)
  } else {
    riskResult = detectFraud(fullText)
  }
  
  // 创建AI回复消息占位
  const aiMessage = { role: 'assistant', type: 'text', content: '' }
  session.messages.push({
    id: createId('msg'),
    createdAt: Date.now(),
    ...aiMessage,
  })

  try {
    // 调用后端API获取AI回复（SSE流式）
    const url = buildApiUrl('/ai/love_app/chat/sse', {
      message: fullText,
      chatId: session.id,
    })

    abortController = new AbortController()
    
    await consumeEventStream(url, {
      signal: abortController.signal,
      onChunk: (chunk) => {
        // 流式更新AI回复内容
        const lastMsg = session.messages[session.messages.length - 1]
        if (lastMsg && lastMsg.role === 'assistant') {
          lastMsg.content += chunk
        }
      },
    })

    // 保存AI回复到短期记忆
    const finalMsg = session.messages[session.messages.length - 1]
    if (finalMsg && finalMsg.role === 'assistant') {
      saveShortMemory(session.id, { role: 'assistant', content: finalMsg.content })
    }

    // 图片风险检测：使用handleRiskResult统一处理弹窗
    if (hasImageContent) {
      // 先检测图片识别内容的风险
      let finalRiskResult = riskResult
      
      // 如果图片识别没有检测到风险，再检测AI回答内容
      if (riskResult.riskLevel === 'none' || riskResult.riskLevel === 'low') {
        const aiResponse = finalMsg?.content || ''
        const aiRiskResult = detectImageRisk(aiResponse)
        if (aiRiskResult.riskLevel === 'high' || aiRiskResult.riskLevel === 'medium') {
          console.log('📷 AI回答中检测到风险:', aiRiskResult.riskLevel, aiRiskResult.fraudType)
          finalRiskResult = aiRiskResult
        }
      }
      
      // 统一使用handleRiskResult处理风险结果（弹窗逻辑一致）
      handleRiskResult(finalRiskResult, fullText, session)
    } else {
      // 非图片：根据风险等级追加风险提示
      handleRiskResult(riskResult, fullText, session)
    }

  } catch (err) {
    console.error('AI回复失败:', err)
    // 错误时也给出基础回复
    const lastMsg = session.messages[session.messages.length - 1]
    if (lastMsg && lastMsg.role === 'assistant' && !lastMsg.content) {
      lastMsg.content = getFallbackReply(fullText, riskResult)
    }
  } finally {
    loading.value = false
    abortController = null
  }
}

// 获取兜底回复（当API调用失败时）
function getFallbackReply(text, riskResult) {
  const roleLabel = userInfo.value.roleLabel || '中青年'
  
  if (riskResult.scene === 'chat') {
    return `你好呀～我是你的专属反诈卫士！有什么我可以帮你的吗？`
  }
  
  if (riskResult.scene === 'knowledge') {
    return `这是一个很好的反诈知识问题！建议你关注以下几点：\n\n1. 不轻信陌生人的电话和短信\n2. 不点击不明链接\n3. 不向陌生人转账\n4. 保护好个人信息和验证码\n\n如需更详细的解答，请稍后再试～`
  }
  
  if (riskResult.riskLevel === 'high') {
    return `⚠️ 检测到高风险内容！请立即停止操作，不要转账！\n\n建议：\n- 拨打110报警\n- 联系银行冻结账户\n- 保存相关证据`
  }
  
  if (riskResult.riskLevel === 'medium') {
    return `⚠️ 检测到可疑内容，请保持警惕！\n\n建议：\n- 核实对方身份\n- 不轻易转账\n- 与家人朋友商量`
  }
  
  return `感谢你的咨询！作为${roleLabel}，请注意防范诈骗风险。如有疑问，请随时告诉我～`
}

function handleInputKeydown(event) {
  if (event.key === 'Enter' && !event.shiftKey) {
    event.preventDefault()
    send()
  }
}

onMounted(() => {
  const restored = restoreSessions()
  if (!restored) {
    openNewSession()
  } else {
    // 恢复会话后，检查当前活动会话是否需要显示欢迎消息
    const currentSession = sessions.value.find((s) => s.id === activeSessionId.value)
    if (currentSession && !currentSession.welcomeShown) {
      sendWelcomeMessage(currentSession)
    }
  }
  // 点击外部关闭菜单
  document.addEventListener('click', closeAllMenus)
  // 自适应进化：系统启动时自动完成更新（控制台展示技术细节）
  simulateAdaptiveEvolution()
  
  // 注册 API 错误处理回调
  setOnApiError((message) => {
    showApiErrorMsg(message)
  })
  
  // 从后端加载用户信息
  fetchUserProfile()
})

onUnmounted(() => {
  document.removeEventListener('click', closeAllMenus)
})
</script>

