}

.video-thumbnail-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

.video-thumbnail-placeholder {
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  background: linear-gradient(135deg, #2a2a3e 0%, #1a1a2e 100%);
  color: rgba(255, 255, 255, 0.6);
}

.video-thumbnail-placeholder .video-icon {
  font-size: 2.5rem;
}

.video-play-overlay {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(0, 0, 0, 0.25);
  transition: background 0.2s;
}

.video-thumbnail:hover .video-play-overlay {
  background: rgba(0, 0, 0, 0.4);
}

.video-play-icon {
  width: 2.4rem;
  height: 2.4rem;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.92);
  color: #1a1a2e;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.9rem;
  padding-left: 3px;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.3);
}

/* ==================== 视频播放器弹窗 ==================== */
.video-player-overlay {
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.85);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 9999;
  padding: 2rem;
  animation: fadeIn 0.2s ease;
}

.video-player-modal {
  background: #000;
  border-radius: 12px;
  width: 100%;
  max-width: 900px;
  max-height: 90vh;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  box-shadow: 0 20px 60px rgba(0, 0, 0, 0.5);
}

.video-player-header {
  display: flex;
  align-items: center;
  padding: 0.6rem 1rem;
  background: #1a1a2e;
  color: #fff;
  border-bottom: 1px solid rgba(255, 255, 255, 0.1);
}

.video-player-title {
  flex: 1;
  font-size: 0.9rem;
  color: rgba(255, 255, 255, 0.9);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.video-player-close {
  background: transparent;
  border: none;
  color: rgba(255, 255, 255, 0.8);
  font-size: 1.2rem;
  cursor: pointer;
  padding: 4px 10px;
  border-radius: 4px;
  transition: all 0.2s;
}

.video-player-close:hover {
  background: rgba(255, 255, 255, 0.1);
  color: #fff;
}

.video-player-body {
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  background: #000;
}

.video-player-video {
  width: 100%;
  max-height: 80vh;
  display: block;
  outline: none;
}

.multimedia-message {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.multimedia-text {
  flex-shrink: 0;
}

.multimedia-media {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
  align-items: flex-start;
}

.media-item {
  flex-shrink: 0;
  max-width: 12rem;
}

.media-item--image {
  max-width: 10rem;
}

.media-item--video {
  max-width: 12rem;
}

.media-item--audio {
  max-width: 14rem;
}

.message-audio {
  width: 16rem;
  max-width: 100%;
}

.audio-card {
  display: flex;
  flex-direction: column;
  gap: 0.3rem;
}

.audio-wave {
  display: flex;
  align-items: flex-end;
  gap: 2px;
  height: 18px;
}

.audio-wave-bar {
  width: 3px;
  border-radius: 999px;
  background: linear-gradient(180deg, #3b82f6, #6366f1);
  animation: wavePulse 1.1s ease-in-out infinite;
}

.audio-wave-bar:nth-child(3n) {
  animation-delay: 0.12s;
}

.audio-wave-bar:nth-child(3n + 1) {
  animation-delay: 0.22s;
}

.audio-wave-bar:nth-child(3n + 2) {
  animation-delay: 0.32s;
}

.audio-duration {
  font-size: 0.72rem;
  color: #787774;
}

/* ==================== 视频格式不支持提示 ==================== */
.video-unsupported {
  width: 100%;
  padding: 2.5rem 2rem;
  text-align: center;
  color: rgba(255, 255, 255, 0.9);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  min-height: 18rem;
}

.video-unsupported-icon {
  font-size: 3rem;
  margin-bottom: 1rem;
  filter: drop-shadow(0 2px 8px rgba(255, 165, 0, 0.4));
}

.video-unsupported-title {
  font-size: 1.1rem;
  margin: 0 0 0.5rem;
  color: #fff;
  font-weight: 600;
}

.video-unsupported-text {
  font-size: 0.85rem;
  color: rgba(255, 255, 255, 0.7);
  margin: 0 0 1rem;
}

.video-unsupported-text strong {
  color: #fbbf24;
  font-family: 'Consolas', 'Monaco', monospace;
  background: rgba(251, 191, 36, 0.15);
  padding: 2px 6px;
  border-radius: 4px;
}

.video-unsupported-tip {
  font-size: 0.8rem;
  line-height: 1.7;
  color: rgba(255, 255, 255, 0.75);
  margin: 0 0 1.5rem;
  max-width: 28rem;
  text-align: left;
}

.video-unsupported-tip strong {
  color: #fbbf24;
  font-weight: 600;
}

.video-unsupported-actions {
  display: flex;
  gap: 0.75rem;
  flex-wrap: wrap;
  justify-content: center;
}

.video-unsupported-actions .btn {
  display: inline-block;
  padding: 0.5rem 1.2rem;
  border-radius: 8px;
  font-size: 0.85rem;
  font-weight: 500;
  text-decoration: none;
  border: none;
  cursor: pointer;
  transition: all 0.2s;
}

.video-unsupported-actions .btn-primary {
  background: linear-gradient(135deg, #4A90D9, #357ABD);
  color: #fff;
}

.video-unsupported-actions .btn-primary:hover {
  background: linear-gradient(135deg, #5B9EE0, #3D86C9);
  transform: translateY(-1px);
}

.video-unsupported-actions .btn-secondary {
  background: rgba(255, 255, 255, 0.12);
  color: rgba(255, 255, 255, 0.9);
  border: 1px solid rgba(255, 255, 255, 0.2);
}

.video-unsupported-actions .btn-secondary:hover {
  background: rgba(255, 255, 255, 0.2);
}

/* ==================== 底部输入区域 ==================== */
.composer {
  position: relative;
  z-index: 2;
  border-top: 1px solid rgba(74, 144, 217, 0.12);
  padding: 0.5rem 0.8rem 0.6rem;
  background: rgba(255, 255, 255, 0.7);
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
}

/* ==================== API 错误提示 ==================== */
.api-error-toast {
  position: fixed;
  top: 24px;
  right: 24px;
  background: #fff;
  border: 1px solid rgba(239, 68, 68, 0.3);
  border-left: 4px solid #ef4444;
  border-radius: 12px;
  padding: 16px 20px;
  display: flex;
  align-items: flex-start;
  gap: 12px;
  box-shadow: 0 12px 48px rgba(0, 0, 0, 0.12);
  z-index: 3000;
  max-width: 420px;
  animation: slideInRight 0.3s ease;
}

@keyframes slideInRight {
  0% { transform: translateX(100px); opacity: 0; }
  100% { transform: translateX(0); opacity: 1; }
}

.api-error-icon {
  font-size: 1.2rem;
  flex-shrink: 0;
  margin-top: 2px;
}

.api-error-content {
  flex: 1;
  min-width: 0;
}

.api-error-title {
  margin: 0 0 4px;
  font-size: 0.9rem;
  font-weight: 600;
  color: #dc2626;
}

.api-error-message {
  margin: 0;
  font-size: 0.8rem;
  color: #6b7280;
  line-height: 1.4;
}

.api-error-close {
  background: none;
  border: none;
  color: #9ca3af;
  cursor: pointer;
  font-size: 1rem;
  padding: 2px;
  flex-shrink: 0;
}

.api-error-close:hover {
  color: #6b7280;
}

/* ==================== 用户资料编辑弹窗 ==================== */
.profile-modal {
  background: rgba(255, 255, 255, 0.98);
  border-radius: 20px;
  width: 90%;
  max-width: 480px;
  max-height: 85vh;
  overflow-y: auto;
  box-shadow: 0 24px 80px rgba(0, 0, 0, 0.2);
  animation: modalSlideUp 0.3s ease;
}

.profile-modal-header {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  padding: 1.25rem 1.5rem;
  border-bottom: 1px solid rgba(74, 144, 217, 0.1);
}

.profile-modal-icon {
  font-size: 1.5rem;
}

.profile-modal-header h3 {
  margin: 0;
  flex: 1;
  font-size: 1.1rem;
  font-weight: 600;
  color: #2F3437;
}

.profile-modal-close {
  background: none;
  border: none;
  color: #9ca3af;
  cursor: pointer;
  font-size: 1.2rem;
  padding: 4px;
  border-radius: 6px;
  transition: all 0.2s;
}

.profile-modal-close:hover {
  background: rgba(0, 0, 0, 0.05);
  color: #6b7280;
}

.profile-modal-body {
  padding: 1.5rem;
}

.profile-field {
  margin-bottom: 1.25rem;
}

.profile-field:last-child {
  margin-bottom: 0;
}

.profile-label {
  display: block;
  font-size: 0.85rem;
  font-weight: 600;
  color: #2F3437;
  margin-bottom: 0.5rem;
}

.profile-desc {
  margin: 0 0 0.75rem;
  font-size: 0.78rem;
  color: #6b7280;
  line-height: 1.4;
}

.profile-input {
  width: 100%;
  padding: 0.6rem 0.8rem;
  border: 1px solid rgba(74, 144, 217, 0.2);
  border-radius: 8px;
  font-size: 0.85rem;
  color: #2F3437;
  background: rgba(255, 255, 255, 0.8);
  box-sizing: border-box;
  transition: border-color 0.2s;
}

.profile-input:focus {
  outline: none;
  border-color: #4A90D9;
  box-shadow: 0 0 0 3px rgba(74, 144, 217, 0.1);
}

.profile-select {
  width: 100%;
  padding: 0.6rem 0.8rem;
  border: 1px solid rgba(74, 144, 217, 0.2);
  border-radius: 8px;
  font-size: 0.85rem;
  color: #2F3437;
  background: rgba(255, 255, 255, 0.8);
  box-sizing: border-box;
  transition: border-color 0.2s;
  cursor: pointer;
  appearance: auto;
}

.profile-select:focus {
  outline: none;
  border-color: #4A90D9;
  box-shadow: 0 0 0 3px rgba(74, 144, 217, 0.1);
}

.profile-value {
  margin: 0;
  font-size: 0.85rem;
  color: #6b7280;
}

.profile-modal-footer {
  padding: 1rem 1.5rem;
  border-top: 1px solid rgba(74, 144, 217, 0.1);
  display: flex;
  justify-content: flex-end;
}

/* ==================== 安全监测报告 ==================== */
.report-section {
  margin-bottom: 1rem;
  padding-bottom: 1rem;
  border-bottom: 1px solid rgba(74, 144, 217, 0.08);
}

.report-section:last-of-type {
  border-bottom: none;
  margin-bottom: 0;
  padding-bottom: 0;
}

.report-section-title {
  margin: 0 0 0.6rem;
  font-size: 0.9rem;
  font-weight: 600;
  color: #2F3437;
}

.report-section-title--urgent {
  color: #dc2626;
}

.report-confidence {
  margin-top: 0.4rem;
  font-size: 0.8rem;
  color: #6b7280;
}

.report-risk-level {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.5rem 1rem;
  border-radius: 8px;
  font-size: 1rem;
  font-weight: 700;
}

.report-risk-level--high {
  background: rgba(239, 68, 68, 0.1);
  color: #dc2626;
  border: 1px solid rgba(239, 68, 68, 0.2);
}

.report-risk-level--medium {
  background: rgba(245, 158, 11, 0.1);
  color: #d97706;
  border: 1px solid rgba(245, 158, 11, 0.2);
}

.report-risk-level--low {
  background: rgba(16, 185, 129, 0.1);
  color: #059669;
  border: 1px solid rgba(16, 185, 129, 0.2);
}

.report-risk-icon {
  font-size: 1.1rem;
}

.report-risk-text {
  font-size: 1rem;
}

.report-info-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0.6rem;
}

.report-info-item {
  padding: 0.5rem 0.7rem;
  background: rgba(74, 144, 217, 0.04);
  border-radius: 8px;
  border: 1px solid rgba(74, 144, 217, 0.08);
}

.report-info-label {
  display: block;
  font-size: 0.75rem;
  color: #6b7280;
  margin-bottom: 0.2rem;
}

.report-info-value {
  display: block;
  font-size: 0.85rem;
  font-weight: 600;
  color: #2F3437;
}

.report-info-value--fraud {
  color: #dc2626;
}

.report-suggestions {
  list-style: none;
  margin: 0;
  padding: 0;
}

.report-suggestions li {
  display: flex;
  align-items: flex-start;
  gap: 0.5rem;
  padding: 0.4rem 0;
  font-size: 0.85rem;
  color: #374151;
  line-height: 1.4;
}

.report-suggestions li:last-child {
  padding-bottom: 0;
}

.suggestion-icon {
  flex-shrink: 0;
  font-size: 0.9rem;
}

.suggestion-urgent {
  background: rgba(239, 68, 68, 0.06);
  border-radius: 8px;
  padding: 0.5rem 0.75rem;
  margin: 0 -0.75rem;
}

.report-persuasion-content {
  padding: 0.75rem 1rem;
  background: rgba(74, 144, 217, 0.04);
  border: 1px solid rgba(74, 144, 217, 0.1);
  border-radius: 10px;
  font-size: 0.85rem;
  color: #374151;
  line-height: 1.6;
  white-space: pre-wrap;
}

.report-section--persuasion {
  margin-top: 0.5rem;
}

.hidden-input {
  display: none;
}

.pending-list {
  margin-bottom: 0.4rem;
  display: flex;
  flex-wrap: wrap;
  gap: 0.4rem;
}

.pending-item {
  border: 1px solid #e2e8f0;
  border-radius: 8px;
  padding: 0.3rem;
  background: #f8fafc;
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
}

.pending-item img {
  width: 4rem;
  height: 4rem;
  border-radius: 6px;
  object-fit: cover;
}

.pending-item button {
  border: none;
  border-radius: 5px;
  background: #ef4444;
  color: #fff;
  font-size: 0.68rem;
  height: 1.3rem;
  cursor: pointer;
}

.pending-item--audio audio {
  width: 10rem;
}

.pending-item--audio .audio-card {
  min-width: 10rem;
}

.media-preview-area {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
  padding: 0.5rem;
  background: rgba(74, 144, 217, 0.06);
  border: 1px solid rgba(74, 144, 217, 0.12);
  border-radius: 8px;
  margin-bottom: 0.35rem;
}

.media-preview-item {
  position: relative;
  border-radius: 8px;
  overflow: hidden;
  background: rgba(255, 255, 255, 0.05);
  border: 1px solid rgba(255, 255, 255, 0.08);
}

.media-preview-item--image {
  width: 5rem;
  height: 5rem;
}

.media-preview-item--audio {
  padding: 0.5rem 0.75rem;
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.media-preview-item--video {
  width: 14rem;
  min-height: 10rem;
  display: flex;
  flex-direction: column;
}

.media-preview-image {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.media-preview-video {
  display: flex;
  flex-direction: column;
  align-items: stretch;
  gap: 0.35rem;
  width: 100%;
}

.media-preview-video-player {
  width: 100%;
  max-height: 12rem;
  border-radius: 6px;
  background: #000;
}

.media-preview-audio {
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.media-icon {
  font-size: 1.2rem;
}

.media-name {
  font-size: 0.75rem;
  color: rgba(255, 255, 255, 0.5);
  max-width: 6rem;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.media-icon-overlay {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  font-size: 1.5rem;
  background: rgba(0, 0, 0, 0.5);
  border-radius: 50%;
  width: 2rem;
  height: 2rem;
  display: flex;
  align-items: center;
  justify-content: center;
}

.media-remove-btn {
  position: absolute;
  top: 0.15rem;
  right: 0.15rem;
  width: 1.2rem;
  height: 1.2rem;
  border-radius: 50%;
  background: rgba(0, 0, 0, 0.6);
  color: #fff;
  border: none;
  font-size: 0.9rem;
  line-height: 1;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 1;
}

.media-remove-btn:hover {
  background: rgba(239, 68, 68, 0.9);
}

.composer-bar {
  border: 1px solid rgba(74, 144, 217, 0.18);
  border-radius: 12px;
  padding: 0.4rem;
  background: rgba(255, 255, 255, 0.85);
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
  box-shadow: 0 4px 24px rgba(74, 144, 217, 0.08);
  display: flex;
  flex-direction: column;
  gap: 0.35rem;
}

.tool-actions {
  display: flex;
  align-items: center;
  gap: 0.4rem;
  flex-wrap: wrap;
}

.tool-btn {
  border: 1px solid rgba(74, 144, 217, 0.15);
  background: rgba(74, 144, 217, 0.05);
  color: #5a6a7e;
  border-radius: 6px;
  height: 1.7rem;
  min-width: 3rem;
  font-size: 0.78rem;
  cursor: pointer;
  transition: all 0.2s;
}

.tool-btn:hover {
  background: rgba(74, 144, 217, 0.12);
  border-color: rgba(74, 144, 217, 0.4);
  color: #1F6C9F;
}

.composer-input {
  width: 100%;
  border: none;
  background: transparent;
  resize: none;
  min-height: 2.4rem;
  max-height: 6rem;
  outline: none;
  color: #2F3437;
  font: inherit;
  line-height: 1.4;
  font-size: 0.88rem;
}

.composer-input::placeholder {
  color: #b0bccf;
}

.send-btn {
  align-self: flex-end;
  border: none;
  border-radius: 8px;
  height: 1.9rem;
  min-width: 4rem;
  background: linear-gradient(135deg, #4A90D9, #357ABD);
  color: #fff;
  font-weight: 500;
  font-size: 0.85rem;
  cursor: pointer;
  transition: all 0.2s;
}

.send-btn:hover {
  background: linear-gradient(135deg, #5B9EE0, #3D86C9);
  transform: translateY(-1px);
  box-shadow: 0 4px 16px rgba(74, 144, 217, 0.3);
}

.send-btn:disabled {
  opacity: 0.4;
  cursor: not-allowed;
  transform: none;
}

@keyframes wavePulse {
  0%,
  100% {
    height: 4px;
  }
  50% {
    height: 100%;
  }
}

@media (max-width: 920px) {
  .doubao-layout {
    grid-template-columns: 1fr;
  }

  .sidebar {
    border-right: none;
    border-bottom: 1px solid rgba(255, 255, 255, 0.08);
    max-height: 12rem;
  }
}

@media (max-width: 600px) {
  .chat-header,
  .message-panel,
  .composer {
    padding-left: 0.6rem;
    padding-right: 0.6rem;
  }

  .message-bubble {
    max-width: 90%;
  }
}

/* ==================== 风险预警弹窗 ==================== */
.risk-modal-overlay {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: rgba(15, 23, 42, 0.7);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 1000;
  animation: fadeIn 0.2s ease;
  backdrop-filter: blur(4px);
}

@keyframes fadeIn {
  from { opacity: 0; }
  to { opacity: 1; }
}

.risk-modal {
  background: rgba(20, 24, 40, 0.98);
  border-radius: 16px;
  width: 90%;
  max-width: 400px;
  overflow: hidden;
  animation: slideUp 0.3s ease;
  box-shadow: 0 25px 50px -12px rgba(0, 0, 0, 0.5);
  border: 1px solid rgba(255, 255, 255, 0.08);
  backdrop-filter: blur(20px);
}

@keyframes slideUp {
  from { transform: translateY(30px); opacity: 0; }
  to { transform: translateY(0); opacity: 1; }
}

.risk-modal--high {
  border: 2px solid #ef4444;
  animation: slideUp 0.3s ease, shake 0.5s ease 0.3s;
}

@keyframes shake {
  0%, 100% { transform: translateX(0); }
  20%, 60% { transform: translateX(-8px); }
  40%, 80% { transform: translateX(8px); }
}

.risk-modal--medium {
  border: 2px solid #f59e0b;
}

.risk-modal--low {
  border: 2px solid #22c55e;
}

.risk-modal-header {
  padding: 16px;
  text-align: center;
  background: linear-gradient(135deg, #f8fafc, #f1f5f9);
}

.risk-modal--high .risk-modal-header {
  background: linear-gradient(135deg, #dc2626, #ef4444);
